// Use a fixed well-known UUID for the singleton settings row
const SETTINGS_ID = "00000000-0000-0000-0000-000000000001";
await sql`
  INSERT INTO notification_settings (
    id, notification_subject_template, notification_body_template,
    quiet_hours_start, quiet_hours_end, timezone, updated_at
  ) VALUES (
    ${SETTINGS_ID}, ${safeSubject}, ${safeBody}, '22:00', '08:00', 'America/New_York', now()
  )
  ON CONFLICT (id) DO UPDATE SET
    notification_subject_template = EXCLUDED.notification_subject_template,
    notification_body_template = EXCLUDED.notification_body_template,
    updated_at = now()
`;

new_string:
// Singleton upsert: fetch existing row id, update if exists, else insert
const [existingSettings] = await sql<{ id: string }[]>`
  SELECT id FROM notification_settings LIMIT 1
`;
if (existingSettings) {
  await sql`
    UPDATE notification_settings
    SET notification_subject_template = ${safeSubject},
        notification_body_template = ${safeBody},
        updated_at = now()
    WHERE id = ${existingSettings.id}
  `;
} else {
  await sql`
    INSERT INTO notification_settings (
      notification_subject_template, notification_body_template,
      quiet_hours_start, quiet_hours_end, timezone, updated_at
    ) VALUES (
      ${safeSubject}, ${safeBody}, '22:00', '08:00', 'America/New_York', now()
    )
  `;
}
